package ch.local.autoscroll;
import android.accessibilityservice.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;
public class ScrollService extends AccessibilityService {
 static final java.util.ArrayDeque<String> history=new java.util.ArrayDeque<>(); static String lastRicardo="none",gestureState="not tested"; static ScrollService instance; static void log(String s){if(history.size()>=30)history.removeFirst();history.addLast(android.os.SystemClock.elapsedRealtime()+" "+s);} static void testOverlay(){if(instance==null||instance.panel==null){log("Overlay unavailable");return;}ScrollService a=instance;a.finish();a.main.setEnabled(false);a.panel.setVisibility(View.VISIBLE);a.overlayState="test visible";a.h.postDelayed(()->{if(a.panel!=null){a.main.setEnabled(true);a.panel.setVisibility(a.target()?View.VISIBLE:View.GONE);a.overlayState=a.target()?"visible":"hidden";}},3000);} static boolean connected=false,detected=false; static String lastPackage="none",overlayState="not created"; final Handler h=new Handler(Looper.getMainLooper()); WindowManager wm; LinearLayout panel; Button main,stop; boolean running=false,paused=false,busy=false; long deadline,remaining,ready; int generation=0; static final String TARGET="com.qxl.Client";
 final Runnable tick=()->step();
 int cfg(String k,int def){return getSharedPreferences("cfg",0).getInt(k,def);}
 boolean foreground=false; boolean target(){return foreground && getSystemService(android.os.PowerManager.class).isInteractive() && !getSystemService(android.app.KeyguardManager.class).isKeyguardLocked();}
 void finish(){generation++;running=false;paused=false;h.removeCallbacks(tick);if(main!=null)main.setText("Start");}
 @Override protected void onServiceConnected(){instance=this;connected=true;log("Service connected");wm=getSystemService(WindowManager.class);panel=new LinearLayout(this);main=new Button(this);main.setText("Start");stop=new Button(this);stop.setText("Stop");panel.addView(main);panel.addView(stop);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.RIGHT;lp.y=100;try{wm.addView(panel,lp);overlayState="created";}catch(RuntimeException ex){overlayState=ex.getClass().getSimpleName();panel=null;return;}panel.setVisibility(View.GONE);main.setOnClickListener(v->{if(!target())return;long now=SystemClock.elapsedRealtime();if(!running){running=true;paused=false;generation++;remaining=new int[]{30,60,90,120,180}[cfg("duration",2)]*1000L;ready=now+new int[]{3,5,10}[cfg("count",1)]*1000L;deadline=ready+remaining;main.setText("Pause");h.post(tick);}else if(!paused){remaining=Math.max(0,deadline-Math.max(now,ready));paused=true;generation++;h.removeCallbacks(tick);main.setText("Resume");}else{paused=false;generation++;ready=now+1000;deadline=ready+remaining;main.setText("Pause");h.post(tick);}});stop.setOnClickListener(v->finish());}
 @Override public void onAccessibilityEvent(AccessibilityEvent e){if(e.getEventType()!=AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED)return; CharSequence pkg=e.getPackageName(); lastPackage=pkg==null?"unknown":pkg.toString(); log(lastPackage);foreground=pkg!=null && TARGET.contentEquals(pkg);detected=foreground;if(foreground)lastRicardo=lastPackage;if(panel==null)return; boolean ok=target();panel.setVisibility(ok?View.VISIBLE:View.GONE);overlayState=ok?"visible":"hidden";if(!ok&&running)finish();}
 void step(){if(!running||paused)return;if(!target()){finish();return;}long now=SystemClock.elapsedRealtime();if(now>=deadline){finish();return;}if(now<ready){main.setText("Pause "+((ready-now+999)/1000));h.postDelayed(tick,200);return;}main.setText("Pause "+((deadline-now+999)/1000));if(busy){h.postDelayed(tick,100);return;}Rect r=new Rect(); if(Build.VERSION.SDK_INT>=30){WindowMetrics m=wm.getCurrentWindowMetrics();r.set(m.getBounds());android.graphics.Insets i=m.getWindowInsets().getInsetsIgnoringVisibility(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());r.left+=i.left;r.top+=i.top;r.right-=i.right;r.bottom-=i.bottom;}else{android.util.DisplayMetrics m=new android.util.DisplayMetrics();wm.getDefaultDisplay().getMetrics(m);r.set(0,0,m.widthPixels,m.heightPixels);}if(r.width()<100||r.height()<300){finish();return;}float top=r.top+r.height()*.10f,bottom=r.bottom-r.height()*.12f;float overlap=new int[]{15,20,25}[cfg("overlap",1)]/100f;float end=bottom-(bottom-top)*(1-overlap);int ms=new int[]{600,800,1000,1500}[cfg("speed",1)];if(deadline-now<ms){h.postDelayed(tick,deadline-now);return;}Path path=new Path();path.moveTo(r.left+r.width()*.45f,bottom);path.lineTo(r.left+r.width()*.45f,end);int token=generation;busy=true;gestureState="dispatching";boolean sent=dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,ms)).build(),new GestureResultCallback(){public void onCompleted(GestureDescription g){gestureState="completed";busy=false;if(token==generation&&running&&!paused)h.postDelayed(tick,cfg("mode",0)==0?new int[]{1500,2500,4000,6000}[cfg("pause",1)]:350);}public void onCancelled(GestureDescription g){gestureState="cancelled";busy=false;if(token==generation)finish();}},null);if(!sent){gestureState="rejected";busy=false;finish();}}
 @Override public void onInterrupt(){finish();} @Override public void onDestroy(){instance=null;connected=false;detected=false;finish();if(panel!=null)wm.removeView(panel);super.onDestroy();}
}